      const p = (a, r) => (CLK[0] + r * Math.sin(a)).toFixed(2) + " " + (-(CLK[2] + r * Math.cos(a))).toFixed(2);
      hands.setAttribute("d", "M" + p(ah + Math.PI, 1) + "L" + p(ah, 3.8) + "M" + p(am + Math.PI, 1.4) + "L" + p(am, 5.6));
