      if (bus) { const e = flota[+bus.getAttribute("data-bus")]; if (e && e !== nocheBus && e.i !== "" && e.i != null) abrir({ tipo: "item", i: +e.i, rapida: false }); else if (e === nocheBus) abrir({ tipo: D.sueno ? "sueno" : "anotar" }); }
